pcall(function()
    for k, v in pairs({isfolder, delfolder, listfiles, delfile}) do
        if not v then return end
    end
    local FolderName, FilePaths = ".UniversalScriptLoader", "/content"
    local FP = FolderName .. FilePaths
    local function delete(pathParam)
        for path, file in next, listfiles(pathParam) do
            if isfolder(file) then
                delete(file)
            else
                pcall(delfile, file)
            end
        end
        pcall(delfolder, pathParam)
    end
    if isfolder(FP) then
        delete(FP)
    end
    print("Cleared cache")
end)

